#include <stdio.h>
#include <stdlib.h>

/* arbitrary precision fibonacci, base 1e9 limbs */
static void addbig(const unsigned int *x, size_t lx,
                   const unsigned int *y, size_t ly,
                   unsigned int *z, size_t *lz)
{
    size_t i, m = lx > ly ? lx : ly;
    unsigned long long carry = 0;
    for (i = 0; i < m; i++) {
        unsigned long long s = carry;
        if (i < lx) s += x[i];
        if (i < ly) s += y[i];
        if (s >= 1000000000ULL) { s -= 1000000000ULL; carry = 1; }
        else carry = 0;
        z[i] = (unsigned int)s;
    }
    if (carry) z[m++] = 1;
    *lz = m;
}

int main(int argc, char **argv)
{
    long long n = 0;
    size_t cap, la = 1, lb = 1, lt = 1, i;
    unsigned int *a, *b, *t, *tmp;

    if (argc > 1) n = strtoll(argv[1], NULL, 10);
    if (n < 0) n = 0;

    cap = (size_t)(n / 32) + 8;
    a = (unsigned int *)calloc(cap, sizeof(unsigned int));
    b = (unsigned int *)calloc(cap, sizeof(unsigned int));
    t = (unsigned int *)calloc(cap, sizeof(unsigned int));
    if (!a || !b || !t) return 1;

    a[0] = 0;
    b[0] = 1;
    for (i = 0; i < (size_t)n; i++) {
        addbig(a, la, b, lb, t, &lt);
        tmp = a; a = b; la = lb;
        b = t; lb = lt;
        t = tmp;
    }

    printf("%u", a[la - 1]);
    for (i = la - 1; i > 0; i--) printf("%09u", a[i - 1]);
    printf("\n");
    free(a); free(b); free(t);
    return 0;
}
